"""
Returns the number of index pairs i<j such that xs[i] + xs[j] == k.
"""
def count_pairs(xs, k):
    if not isinstance(xs, list):
        raise TypeError("The first argument must be a list.")
    count = 0
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] + xs[j] == k:
                count += 1
    return count
